  var brand=Card("Make it yours","The approval strip is what appears in ChatGPT whenever something needs your OK.");BrandPicker(brand);
  var daily=Card("Your daily browser, on request","Prefer ChatGPT to work in the Chrome or Edge you already use, with your own signed-in accounts? Install the small YGPT browser extension after setup: in Chrome or Edge open the extensions page, turn on Developer mode, choose Load unpacked and select the extension folder inside the application folder you picked above. Then, while YGPT is running, open http://127.0.0.1:19341 in that browser and paste the pairing token into the extension. YGPT only ever works inside its own tab group there; your own tabs are never read or touched. Skipping this is fine: the built-in isolated browser always works.");
