 void ConnectionPage(){var p=Card("OpenAI Secure MCP Tunnel","Recommended for an eligible personal account or workspace. Your server stays private.");Radio(p,2,"Secure MCP Tunnel — Recommended");if(mode.SelectedIndex==2){Field(p,"tunnel","Dedicated Secure MCP Tunnel ID","Paste the entire tunnel_… value. A Tunnel ID is not an API key. Do not reuse an active connection owned by another instance.");Action(p,"Open official OpenAI Tunnels",()=>Open("https://platform.openai.com/settings/organization/tunnels"));Action(p,"Paste Tunnel ID",()=>fields["tunnel"].Text=Clipboard.GetText().Trim(),"paste-tunnel");Action(p,"Copy suggested Tunnel name",()=>Clipboard.SetText(SuggestedTunnelName),"copy-tunnel-name");Action(p,"Copy suggested Tunnel description",()=>Clipboard.SetText(SuggestedTunnelDescription),"copy-tunnel-description");Guide(p,"Create tunnel — field by field",new[]{"Name  ·  YGPT Local","Description  ·  Private MCP connection for my Windows PC","Organizations  ·  the Platform organization owning your runtime key","ChatGPT workspaces  ·  the actual workspace where you will install the plugin","Create → copy the complete tunnel_… ID"});Text(p,"No Tunnels page? You need organization-level Tunnels Read + Manage to create, and Read + Use to run. Ask that organization's owner; a model API project role alone may not be enough.",12,false,Muted);}
