 void CredentialsPage(){if(Mode()=="local-only"){Card("Local testing needs no remote credential","This mode is not connected to ChatGPT. Configure a private Tunnel or protected HTTPS route later for remote use.");return;}var p=Card(Mode()=="secure-tunnel"?"A runtime key for the Tunnel Client":"Credentials for your Cloudflare route",Mode()=="secure-tunnel"?"This key authenticates the local Tunnel Client. Setup does not call a GPT generation model, and ChatGPT normally asks for the Tunnel ID, not this key.":"Cloudflare credentials run or create the selected protected route. They do not require an OpenAI model API key.");var saved=YGPTApp.Secrets(data);string id=mode.SelectedIndex==2?"runtimeKey":mode.SelectedIndex==0?"token":"apiToken",key=id=="token"?"tunnelToken":id;
