  if(mode.SelectedIndex==2){Action(p,"Open official API Keys",()=>Open("https://platform.openai.com/api-keys"));Action(p,"Copy suggested API key name",()=>Clipboard.SetText(SuggestedApiKeyName),"copy-api-key-name");Guide(p,"Create new secret key — every field",new[]{"Owned by  ·  You for personal use; a service account only if your organization intends it","Name  ·  YGPT Local Tunnel Runtime","Project  ·  a project in the intended Platform organization","Expiration  ·  Never expire only if offered and allowed by your policy; you can revoke or rotate it","Permissions  ·  use a dedicated restricted key; Tunnels Read + Use is organization-level RBAC","Copy the one-time secret here. Do not put it in the ChatGPT plugin form."});Text(p,"Long-lived keys are convenient but remain usable after a leak until revoked. Never weaken an organization expiry policy. A missing permission is not fixed by choosing All blindly.",12,false,Muted);}
  else if(mode.SelectedIndex==0)Text(p,"This connector token runs an existing route; it does not create DNS or grant owner OAuth access.");else if(mode.SelectedIndex==1)Text(p,"The token needs Cloudflare Tunnel Edit and DNS Edit for the selected account/zone. It differs from a connector token.");}
 void InstallPage(){var p=Card("Review this installation");Text(p,"Application"+"  ·  "+fields["install"].Text+"\n"+"Private data"+"  ·  "+data+"\n"+"Authorized work"+"  ·  "+fields["folder"].Text+"\nConnection  ·  "+Mode()+"\nAuto-start  ·  "+(startup.IsChecked==true?"On":"Off")+"\nAuto-cleanup  ·  "+(cleanup.IsChecked==true?"On":"Off"));Text(p,"Existing encrypted keys and your connection identity are preserved. A repair first checks that owned work has finished. No other active tunnel is stopped.");CleanupPlan(p);}
