 void ChatGPTPage(){if(Mode()=="local-only"){var local=Card("Local-only: ChatGPT is not connected","A loopback service is reachable only on this PC. Do not enter 127.0.0.1 in a remote ChatGPT connector. Local testing is not remote acceptance.");Action(local,"Choose a remote connection",()=>{step=2;Render();});return;}var p=Card("Finish the connection in ChatGPT");Text(p,"Use the official form in your own account. YGPT Local does not log in or accept risk warnings for you.");Action(p,"Open ChatGPT Plugins",()=>Open("https://chatgpt.com/plugins"));Guide(p,"Add custom MCP server — field by field",new[]{"Icon  ·  assets/brand/plugin-icon-256.png (256 × 256, under 10 KB; the same folder keeps the earlier icon editions)","Name  ·  YGPT Local","Description  ·  "+SuggestedPluginDescription,Mode()=="secure-tunnel"?"Connection  ·  Tunnel; paste your full tunnel_… ID":"Connection  ·  Server URL; enter your stable HTTPS /mcp URL",Mode()=="secure-tunnel"?"Authentication  ·  No authentication for this dedicated PRIVATE Tunnel only":"Authentication  ·  OAuth; approve using the local owner pairing key","Read the risk warning → I understand and want to continue → Create as a plugin → install personally"});
  Text(p,Mode()=="secure-tunnel"?"No authentication means no additional application OAuth in ChatGPT. The OpenAI runtime key, Tunnel identity and local protections still apply. The runtime API key is not entered again here.":"Public HTTPS remains OAuth protected. Never choose anonymous access for this route.",13,false,Muted);
  Action(p,"Copy plugin name",()=>Clipboard.SetText("YGPT Local"));Text(p,"Suggested plugin description: "+SuggestedPluginDescription,13,false,Muted);Action(p,"Copy plugin description",()=>Clipboard.SetText(SuggestedPluginDescription),"copy-plugin-description");Action(p,"Copy endpoint / Tunnel ID",()=>{var x=HostCore.Read(Path.Combine(data,"connection.json"));Clipboard.SetText(Mode()=="secure-tunnel"?HostCore.S(x,"tunnelId"):HostCore.S(x,"publicOrigin")+"/mcp");});Action(p,"Open icon folder",()=>Open(Path.Combine(install,"assets","brand")));
