 void FinishPage(){var p=Card("One real, read-only task");Text(p,"In a new ChatGPT conversation, select @YGPT Local and paste the test below. It lists only your verification folder and reads a harmless random marker. Local ping does not count.");Action(p,"Copy first-task prompt",()=>Clipboard.SetText(FirstPrompt()),"copy-first-task");Action(p,"Check first real tool result",()=>RefreshStatus(true),"check-first-task");StatusRows(p);
