 void Maintenance(){Expander(body,"Advanced maintenance",p=>{Action(p,"Review storage / cleanup receipt",()=>{string text="No cleanup receipt yet.";try{var r=HostCore.Read(Path.Combine(data,"post-install-cleanup-receipt.json"));text="Cleanup: "+HostCore.S(r,"state")+"\nFiles removed: "+HostCore.S(r,"totalDeleted")+"\nBytes reclaimed: "+HostCore.S(r,"totalBytesReclaimed")+"\nSkipped: "+HostCore.S(r,"skipped")+"\nPrivate data, snapshots and maintenance files are retained.";}catch{}MessageBox.Show(text,"YGPT Local");});Action(p,"Retry eligible cleanup after verified first use",()=>{var r=InstallCleanup.Run(data,install);message.Foreground=B(Muted);message.Text="Cleanup: "+HostCore.S(r,"state");RefreshStatus(false);});Action(p,"Start connection",()=>HostCore.Start(install,data));Action(p,"Pause after owned work finishes",()=>YGPTApp.StopForMaintenance(data));Action(p,"Rotate local pairing keys…",()=>{if(MessageBox.Show("This disconnects existing paired clients. External API keys are not revoked. Continue?","YGPT Local",MessageBoxButton.YesNo,MessageBoxImage.Warning)!=MessageBoxResult.Yes)return;YGPTApp.StopForMaintenance(data);var s=YGPTApp.Secrets(data);foreach(var k in new[]{"localKey","ownerKey","tunnelKey"})s[k]=HostCore.NewKey();YGPTApp.SaveSecrets(data,s);HostCore.Start(install,data);});Action(p,"Open external key revocation page",()=>Open(Mode()=="secure-tunnel"?"https://platform.openai.com/api-keys":"https://dash.cloudflare.com/profile/api-tokens"));Action(p,"Repair / upgrade information",()=>Open("https://github.com/jclllycf/ygpt-local/releases"));Action(p,"Uninstall application (keep private data)",Uninstall);},"advanced-maintenance");}
 void StatusRows(Panel p){var row=new TextBlock{Text=statusText,TextWrapping=TextWrapping.Wrap,LineHeight=24,FontSize=14,Margin=new Thickness(0,4,0,16)};AutomationProperties.SetAutomationId(row,"connection-dashboard");dashboards.Add(row);p.Children.Add(row);RefreshStatus(false);}
 string Generation(){try{return HostCore.S(HostCore.Read(Path.Combine(data,"first-use-challenge.json")),"generation");}catch{return generation;}}
 string FirstPrompt(){var c=HostCore.Read(Path.Combine(data,"first-use-challenge.json"));string p=HostCore.S(c,"path");return "Use YGPT Local to list this verification folder and read its marker file: "+Path.GetDirectoryName(p)+"\n"+p+"\n"+"Tell me the exact marker. Read only; do not execute commands or modify files.";}
 async void RefreshStatus(bool show){if(checking)return;checking=true;try{statusText=await Task.Run(()=>{var lines=new List<string>();try{var h=HostCore.Control(data,"status");localReady=HostCore.B(h,"localReady");lines.Add((localReady?"✓  ":"○  ")+"Local Broker / Engine: "+(localReady?"Ready":"Not verified"));lines.Add("Tools: "+HostCore.S(h,"publicTools")+" public + "+HostCore.S(h,"appOnly")+" App-only");}catch{localReady=false;lines.Add("○  MCP Engine: Not yet invoked. Secure Tunnel may be ready while the on-demand MCP process waits for ChatGPT's first actual tool call.");}try{var w=HostCore.Read(Path.Combine(data,"watchdog-health.json"));bool fresh=(DateTime.UtcNow-DateTime.Parse(HostCore.S(w,"at")).ToUniversalTime()).TotalSeconds<25;lines.Add("Watchdog: "+(fresh?HostCore.S(w,"phase"):"No recent heartbeat — verify task is running")+"  ·  Reconnects: "+HostCore.S(w,"restarts"));int retry; if(Int32.TryParse(HostCore.S(w,"retryInSeconds"),out retry)&&retry>0&&fresh)lines.Add("Next automatic retry: about "+retry+" seconds (the Watchdog is alive)");bool tunnelReady=fresh&&HostCore.B(w,"tunnelConnected");lines.Add("Tunnel: "+(tunnelReady?"Ready (OpenAI Tunnel Client connected)":"Not verified"));if(tunnelReady&&!localReady)lines.Add("Next: Create/connect the ChatGPT plugin and run the first read-only tool call. Local Engine starts on demand.");string e=HostCore.S(w,"lastError");if(e!=""){lines.Add("Last known problem: "+e);switch(e){case "RUNTIME_KEY_INVALID_OR_EXPIRED":lines.Add("Action: replace the OpenAI Tunnel runtime key; do not paste it into ChatGPT.");break;case "TUNNEL_PERMISSION_OR_WORKSPACE_DENIED":lines.Add("Action: verify Tunnels Read + Use permission, organization and ChatGPT workspace.");break;case "TUNNEL_DNS_FAILURE":case "TUNNEL_NETWORK_UNREACHABLE":lines.Add("Action: inspect Windows network/DNS and system proxy in this PC or Sandbox.");break;case "TUNNEL_PROXY_FAILURE":lines.Add("Action: check the proxy used by Tunnel Client; no credentials belong in the URL.");break;case "TUNNEL_TLS_OR_CERTIFICATE_ERROR":lines.Add("Action: check Windows clock, TLS interception and trusted certificates.");break;case "OPENAI_TUNNEL_RATE_LIMITED":lines.Add("Action: allow Tunnel rate limiting to recover; do not recreate the Tunnel.");break;case "TUNNEL_CLIENT_ARGUMENT_ERROR":lines.Add("Action: the packaged official tunnel-client and arguments may be incompatible.");break;}}}catch{}try{lines.Add("Auto-start: "+(HostCore.B(HostCore.Read(Path.Combine(data,"connection.json")),"autoStart")?"Configured":"Off"));}catch{}string g=Generation();lines.Add(g!=""&&HostCore.ProofValid(data,g)?"✓  Authenticated remote marker read — confirm the same result in ChatGPT":"○  First real ChatGPT task: Not verified");try{var r=HostCore.Read(Path.Combine(data,"post-install-cleanup-receipt.json"));lines.Add("Cleanup: "+HostCore.S(r,"state")+" / "+HostCore.S(r,"totalDeleted")+" files / "+HostCore.S(r,"totalBytesReclaimed")+" bytes");}catch{lines.Add("Cleanup: waiting for first use and setup exit");}return String.Join("\n",lines);});foreach(var row in dashboards)row.Text=statusText;if(show){message.Foreground=B(Muted);message.Text="Checks updated. Saved ciphertext does not prove API permissions; inspect the actual ChatGPT result.";}}finally{checking=false;}}
 async void Next(object sender,RoutedEventArgs e){if(busy)return;try{if(step==0){if(consent.IsChecked!=true)throw new Exception("Confirm local access before installing.");if(!Directory.Exists(fields["folder"].Text))throw new Exception("Choose an existing working folder.");YGPTApp.ValidateInstallTarget(fields["install"].Text);if(HostCore.Full(fields["folder"].Text)==Path.GetPathRoot(fields["folder"].Text).TrimEnd('\\'))throw new Exception("Choose a working folder, not a whole drive.");}if(step==1){int port;if(!Int32.TryParse(fields["port"].Text,out port)||port<1024||port>65535)throw new Exception("Port must be 1024–65535");}if(step==2&&Mode()=="secure-tunnel"&&!System.Text.RegularExpressions.Regex.IsMatch(fields["tunnel"].Text.Trim(),@"^tunnel_(?:[a-z0-9]{4}_)?[a-z0-9]{32}$"))throw new Exception("Paste the complete tunnel_… ID from your intended organization and workspace.");if(step==2&&mode.SelectedIndex==1&&createConsent.IsChecked!=true)throw new Exception("Confirm the specific Cloudflare resource creation.");if(step==4){await Install();step=5;Render();RefreshStatus(true);return;}if(step==7){Close();return;}step++;Render();}catch(Exception ex){Error(ex);}}
