  var secretValues=passwords.ToDictionary(x=>x.Key,x=>x.Value.Password);bool clean=cleanup.IsChecked==true,ownSource=sourceCleanup.IsChecked==true;int setupPid=Process.GetCurrentProcess().Id;long birth=Process.GetCurrentProcess().StartTime.ToUniversalTime().Ticks;
  await Task.Run(()=>{
   if(File.Exists(Path.Combine(install,".ygpt-install.json"))){installStage="verify safe repair ownership";HostCore.PrepareOwnedRepair(install,data);}installStage="extract verified payload";YGPTApp.InstallPayload(install);if(File.Exists(Path.Combine(data,"ygpt.config.json")))data=YGPTApp.UpgradeData(install,data);else data=HostCore.DataDir(install);settings["dataDir"]=data;installStage="prepare protected data directory";YGPTApp.PrivateDirectory(data);var s=YGPTApp.Secrets(data);foreach(string key in new[]{"ownerKey","localKey","tunnelKey","verificationKey"})if(!s.ContainsKey(key))s[key]=HostCore.NewKey();foreach(var pair in secretValues)if(pair.Value.Length>0)s[pair.Key=="token"?"tunnelToken":pair.Key]=pair.Value;installStage="store encrypted local credentials";YGPTApp.SaveSecrets(data,s);installStage="provision MCP configuration";
   var result=HostCore.Json.Deserialize<Dictionary<string,object>>(YGPTApp.Node(install,"service/provision.mjs",null,HostCore.Json.Serialize(settings)));if(!HostCore.B(result,"ok"))throw new Exception(HostCore.S(result,"message"));
   installStage="prepare first read-only test";generation=Guid.NewGuid().ToString("N");string directory=Path.Combine(Convert.ToString(settings["projectRoot"]),"YGPT-Verification-"+generation.Substring(0,8));Directory.CreateDirectory(directory);string marker=Path.Combine(directory,"marker.txt");File.WriteAllText(marker,"YGPT_FIRST_READ_"+Guid.NewGuid().ToString("N"),new System.Text.UTF8Encoding(false));HostCore.Save(Path.Combine(data,"first-use-challenge.json"),new{generation=generation,path=marker,sha256=HostCore.Hash(marker),createdAt=DateTime.UtcNow.ToString("o")});
   var entries=new List<Dictionary<string,object>>();if(!HostCore.Within(source,install)){var entry=InstallCleanup.Entry(source,generation,"setup-download",Path.GetDirectoryName(source),true);entry["explicitFileConsent"]=ownSource;entry["cleanupEligibility"]=ownSource;entries.Add(entry);}InstallCleanup.Record(data,install,generation,entries,clean,setupPid,birth);installStage="register Windows automatic startup";YGPTApp.Register(install,data,(bool)settings["autoStart"]);installStage="start the background Watchdog";HostCore.Start(install,data);installed=true;
  });
 }catch(Exception ex){throw new InvalidOperationException("Setup stopped during '"+installStage+"': "+ex.Message+". No unrelated application files will be removed. Do not manually create Watchdog health state.",ex);}finally{busy=false;next.IsEnabled=true;back.IsEnabled=true;}}
 public void Uninstall(){if(MessageBox.Show("Uninstall this application and stop its connection? Private settings, encrypted credentials and snapshots are retained. This is not installer-download cleanup.","YGPT Local",MessageBoxButton.YesNo,MessageBoxImage.Warning)!=MessageBoxResult.Yes)return;YGPTApp.StopForMaintenance(data);string helper=Path.Combine(Path.GetTempPath(),"YGPTLocal-Uninstall-"+Guid.NewGuid().ToString("N")+".exe");File.Copy(Path.Combine(install,"YGPTLocal.exe"),helper);Process.Start(new ProcessStartInfo(helper,"--uninstall-worker --install-dir "+HostCore.Q(install)+" --data-dir "+HostCore.Q(data)){UseShellExecute=false,CreateNoWindow=true,WindowStyle=ProcessWindowStyle.Hidden});Close();}
